@Override
    public int read( ByteBuffer dst ) throws IOException
    {
        int toRead = dst.remaining();
        plainIn.flip();
        if ( plainIn.remaining() >= toRead )
        {
            bufferCopy( plainIn, dst );
            plainIn.compact();
        }
        else
        {
            dst.put( plainIn );             
            do
            {
                plainIn.clear();            
                unwrap( dst );              
            }
            while ( dst.remaining() > 0 );  
        }
        return toRead;
    }

