@Override
    public int read( ByteBuffer dst ) throws IOException
    {
        int toRead = dst.remaining();
        plainIn.flip();
        if ( plainIn.hasRemaining() )
        {
            bufferCopy( plainIn, dst );
            plainIn.compact();
        }
        else
        {
            plainIn.clear();            
            unwrap( dst );              
        }
        return toRead - dst.remaining();
    }

