        {
            @Override
            public Iterator<Property<V>> iterator()
            {
                final Iterator<String> keys = map.keys().iterator();
                return new Iterator<Property<V>>()
                {
                    @Override
                    public boolean hasNext()
                    {
                        return keys.hasNext();
                    }
