                    {
                        String key = keys.next();
                        Value value = map.value( key );
                        return InternalProperty.of( key, mapFunction.apply( value ) );
                    }
                    @Override
                    public void remove()
                    {
                        keys.remove();
                    }
                };
            }
        };
    }

